public static String applyRelativePath(String path, String relativePath) {
    // Remove leading '/' from the relative path
    relativePath = relativePath.startsWith("/") ? relativePath.substring(1) : relativePath;

    // Split the path and relative path into lists of directory components
    List<String> pathList = new ArrayList<>(Arrays.asList(path.split("/")));
    List<String> relativePathList = new ArrayList<>(Arrays.asList(relativePath.split("/")));

    // Traverse the relative path, adding each component to the path list
    for (String component : relativePathList) {
        pathList.add(component);
    }

    // Join the components back into a single path
    return String.join("/", pathList);
}

